impl Probe{fn new(row:i32,col:i32,xf:i32,mutate:bool)->Self{Self{base:CellRecord::new__3(row,col,xf),trace:RefCell::new(vec![]),mutate}}}
impl CellRecordValue for Probe{fn serializeValue(&self,out:&mut dyn LittleEndianOutput){self.trace.borrow_mut().push("serializeValue");out.writeShort(4660);}fn getValueDataSize(&self)->i32{self.trace.borrow_mut().push("valueSize");2}}
impl CellRecordText for Probe{fn appendValueText(&self,sb:&mut String){self.trace.borrow_mut().push("append");sb.push_str("VALUE");}fn getRecordName(&self)->Option<String>{self.trace.borrow_mut().push("name");if self.mutate{self.base.setRow(42);}Some("PROBE".into())}}
