fn fields(p:&Probe)->Value{json!([p.base.getRow(),p.base.getColumn()as i32,p.base.getXFIndex(),p.base._columnIndex.get()])}
fn call(f:impl FnOnce())->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(_)=>json!({"result":"ok","value":null}),Err(e)=>{let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");json!({"result":s.split(':').next().unwrap()})}}}
fn one(a:&Value)->Value{let p=Probe::new(a["row"].as_i64().unwrap()as i32,a["col"].as_i64().unwrap()as i32,a["xf"].as_i64().unwrap()as i32,a["mutate"].as_bool().unwrap());let mut r=json!({"fields":fields(&p)});r["string"]=json!(p.base.toString(&p));r["afterString"]=fields(&p);r["attributeNull"]=json!(p.base.getCellAttribute().is_none());let q=Probe::new(7,8,9,false);p.base.copyBaseFields(Some(&q.base));r["copy"]=fields(&q);let interface:&dyn CellValueRecordInterface=&p.base;interface.setRow(a["setRow"].as_i64().unwrap()as i32);interface.setColumn(a["setCol"].as_i64().unwrap()as i16);interface.setXFIndex(a["setXf"].as_i64().unwrap()as i32);let mut out=LittleEndianByteArrayOutput::new();let size=p.serialize(&mut out);r["set"]=fields(&p);r["bytes"]=json!(out.get_bytes().iter().map(|b|format!("{b:02x}")).collect::<String>());r["size"]=json!(size);r["trace"]=json!(p.trace.borrow().clone());r["nullCopy"]=call(||p.base.copyBaseFields(None));r}
#[test]fn original_android_cell_record_base_and_abstract_dispatch(){let root=std::path::PathBuf::from(std::env::var("SS_CORE_PROOF_ROOT").unwrap_or_else(|_|env!("CARGO_MANIFEST_DIR").into()));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/cell-record-r0b65");let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let actual=json!(input["base"].as_array().unwrap().iter().map(one).collect::<Vec<_>>());std::fs::write(p.join("rust-base.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();assert_eq!(actual,java["base"]);}
